module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] win [0:20];
  integer i, j, mid;
  reg [7:0] t;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) win[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      // Insert new sample at the beginnning of the window
      win[0] <= x;
      // Sort the window (insertion sort, a bit unoptimized)
      for (i = 1; i < 21; i = i + 1) begin
        t = win[i];
        j = i;
        while (j > 0 && win[j-1] > t) begin
          win[j] <= win[j-1];
          j = j - 1;
        end
        win[j] <= t;
      end
      // Output the middle value
      mid = 10;
      y <= {8'b0, win[mid]};
    end
  end
endmodule

